import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"Glossary Map","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/GLOSSARY-MAP.md"},"headers":[],"relativePath":"GLOSSARY-MAP.md","filePath":"GLOSSARY-MAP.md","lastUpdated":1792368169000}`),a={name:`GLOSSARY-MAP.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="glossary-map" tabindex="-1">Glossary Map <a class="header-anchor" href="#glossary-map" aria-label="Permalink to “Glossary Map”">​</a></h1><p><code>pumpkin-plugins</code> is an ecosystem umbrella with distinct domain contexts. The contexts support the same project goals but have different users, responsibilities, and language. Glossaries are created only when a context has shared terms worth recording.</p><h2 id="contexts" tabindex="-1">Contexts <a class="header-anchor" href="#contexts" aria-label="Permalink to “Contexts”">​</a></h2><ul><li><a href="./GLOSSARY">Pumpkin Plugin API</a>, implemented in <a href="https://github.com/filiphsps/pumpkin-plugins/tree/master/tools/pumpkin-api" target="_blank" rel="noreferrer"><code>tools/pumpkin-api/</code></a>: defines the host contract that Pumpkin plugins compile against. This is the only context glossary currently maintained.</li><li>Plugins in <a href="https://github.com/filiphsps/pumpkin-plugins/tree/master/packages" target="_blank" rel="noreferrer"><code>packages/</code></a>: provide behavior for players and server operators.</li><li>Developer tools in <a href="https://github.com/filiphsps/pumpkin-plugins/tree/master/tools" target="_blank" rel="noreferrer"><code>tools/</code></a>: help authors build, test, document, publish, and maintain plugins. Published packages also serve authors working in standalone repositories.</li><li>Reusable GitHub Actions in <a href="https://github.com/filiphsps/pumpkin-plugins/tree/master/actions" target="_blank" rel="noreferrer"><code>actions/</code></a>: automate plugin signing, verification, and Market publishing workflows.</li><li>Editor extensions in <a href="https://github.com/filiphsps/pumpkin-plugins/tree/master/extensions" target="_blank" rel="noreferrer"><code>extensions/</code></a>: support authoring workflows around the Minecraft ecosystem.</li></ul><h2 id="relationships" tabindex="-1">Relationships <a class="header-anchor" href="#relationships" aria-label="Permalink to “Relationships”">​</a></h2><ul><li>Plugin packages target Pumpkin&#39;s host API and use the developer tools where appropriate.</li><li>GitHub Actions support release and distribution workflows for plugin artifacts.</li><li>Editor extensions support contributors and plugin authors; they are part of the project when they materially serve those workflows.</li></ul>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};